    MavenLoggerFactory mavenLoggerFactory = new MavenLoggerFactory();
    mavenLoggerFactory.setLogLevelRecorder(new LogLevelRecorder("ERROR"));
    assertTrue(mavenLoggerFactory.getLogLevelRecorder().isPresent());
